function AuditLogs(){const [query,setQuery]=useState(''),[detail,setDetail]=useState(null);const rows=auditRows.filter(r=>r.join(' ').toLowerCase().includes(query.toLowerCase()));return <><PageTitle eyebrow="APPEND-ONLY OPERATIONAL RECORD" title="Audit Logs" subtitle="Traceable record of model outputs, evidence, recommendations and operator decisions"/><section className="glass filter-bar audit-filter"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search case, operator, event type or configuration"/><button className="date-filter">Event type: All</button><button className="date-filter">Export record ↗</button></section><section className="glass case-table-wrap"><table className="case-table audit-table"><thead><tr>{['TIMESTAMP','CASE ID','OPERATOR','EVENT TYPE','AI OUTPUT','RISK','RECOMMENDATION','HUMAN DECISION','CONFIG'].map(h=><th key={h}>{h}</th>)}<th/></tr></thead><tbody>{rows.map((r,i)=><tr key={i} onClick={()=>setDetail(r)}>{r.map((x,j)=><td key={j}>{j===5?<Risk risk={x}/>:j===7&&x!=='—'?<Pill tone="success">{x}</Pill>:x}</td>)}<td><button className="row-open">View →</button></td></tr>)}</tbody></table></section>{detail&&<aside className="audit-drawer"><button onClick={()=>setDetail(null)}>×</button><p className="eyebrow">AUDIT EVENT DETAIL</p><h2>{detail[3]}</h2><Pill tone="violet">{detail[8]}</Pill><div className="drawer-lines"><span>Input / context <b>{detail[1]} · privacy-safe evidence bundle</b></span><span>Evidence used <b>Redacted transcript, fusion markers, intake metadata</b></span><span>AI assessment <b>{detail[4]} · {detail[5]} risk tier</b></span><span>Retrieved guidance <b>{detail[6]}</b></span><span>Human operator decision <b>{detail[7]}</b></span><span>Timestamp <b>2026-09-15 {detail[0]} UTC</b></span></div><p className="disclaimer">AI Recommendation and Human Operator Decision are distinct audit events.</p></aside>}</>}
function Pipeline(){const stages=[['Layer 0','Intake Ingested','COMPLETED','12:41:02','Portal text · consent declaration','—'],['Layer 1','Privacy / PII Redaction + Evidence Fusion','COMPLETED','12:41:04','Redacted transcript · evidence bundle','0.94'],['Layer 2','Vulnerability / Distress Assessment','COMPLETED','12:41:05','SVI 78 · contributing evidence','0.92'],['Risk & Triage','Risk tier classified','COMPLETED','12:41:05','HIGH · operator review required','0.92'],['Layer 4','Service Guidance / SOP Retrieval','COMPLETED','12:41:06','NHAA SOP 4.2 matched','0.94'],['Governance','Operator Review','WAITING','12:41:07','Awaiting human authorization','—'],['Outcome','Confirmed Service Pathway','WAITING','—','No action executed','—']];return <><PageTitle eyebrow="OBSERVABILITY / NO AUTONOMOUS ROUTING" title="Pipeline Monitor" subtitle="End-to-end case processing visibility"/><section className="monitor-stats">{[['42ms','Processing latency'],['18','Cases processed'],['3','Awaiting review'],['0','Failed stages']].map(([v,l])=><article className="glass stat-card" key={l}><strong>{v}</strong><span>{l}</span></article>)}</section><div className="pipeline-layout"><section className="pipeline-list">{stages.map((s,i)=><React.Fragment key={s[1]}><article className="glass stage-card"><span className="stage-number">{String(i+1).padStart(2,'0')}</span><div><small>{s[0]}</small><h3>{s[1]}</h3><p>{s[4]}</p></div><div className="stage-meta"><Pill tone={s[2]==='COMPLETED'?'success':'waiting'}>{s[2]}</Pill><span>{s[3]}</span><b>{s[5]!=='—'&&`Confidence ${s[5]}`}</b></div></article>{i<stages.length-1&&<div className="stage-line"/>}</React.Fragment>)}</section><aside className="glass activity"><p className="eyebrow">LIVE PIPELINE ACTIVITY</p><h3>Case VC-2048</h3>{['[12:41:02] Case VC-2048 received','[12:41:03] PII redaction completed','[12:41:04] Evidence fusion completed','[12:41:05] SVI evaluated','[12:41:05] Risk tier classified: HIGH','[12:41:06] SOP guidance retrieved','[12:41:07] Awaiting operator review'].map(x=><p className="activity-line" key={x}><i/> {x}</p>)}<div className="activity-note">Observability only. No service pathway is executed without human authorization.</div></aside></div></>}
