function LocalizedApp(){const [page,setPage]=useState('cases'),[cases,setCases]=useState(demoCases),[selected,setSelected]=useState(demoCases[0]),[connected,setConnected]=useState(false),[apiError,setApiError]=useState(''),[locale,setLocale]=useState(()=>localStorage.getItem('dashboard_locale')||'en'),[accessible,setAccessible]=useState(()=>localStorage.getItem('dashboard_accessible')==='true');const loadDetail=caseId=>api(`/case/${encodeURIComponent(caseId)}`);const refresh=async preferredCaseId=>{try{const payload=await api('/cases');const list=Array.isArray(payload)?payload:payload?.cases||[];setConnected(true);setApiError('');setCases(list);const target=preferredCaseId||selected?.case_id||list[0]?.case_id;setSelected(target&&list.some(item=>item.case_id===target)?await loadDetail(target):null)}catch(error){setConnected(false);setApiError(`Live API unavailable: ${error.message}. Showing local demo data; operator actions are disabled.`);setCases(demoCases);setSelected(demoCases[0])}};const selectCase=async summary=>{if(!connected)return setSelected(summary);try{setSelected(await loadDetail(summary.case_id));setApiError('')}catch(error){setApiError(`Could not load ${summary.case_id}: ${error.message}`)}};const submitCase=async caseId=>{await refresh(caseId);setPage('cases')};const recordAction=async payload=>{if(!selected?.case_id)throw new Error('No case is selected.');await api(`/case/${encodeURIComponent(selected.case_id)}/confirm`,{method:'POST',body:JSON.stringify(payload)});await refresh(selected.case_id)};useEffect(()=>{refresh()},[]);useEffect(()=>{document.documentElement.lang=locale;localStorage.setItem('dashboard_locale',locale)},[locale]);useEffect(()=>{localStorage.setItem('dashboard_accessible',String(accessible))},[accessible]);const View=page==='cases'?<FeatureActiveCases cases={cases} selected={selected} onSelect={selectCase} connected={connected} refresh={refresh} onSubmitted={submitCase} onRecord={recordAction} error={apiError} locale={locale}/>:page==='audit'?<LocalizedAuditLogs locale={locale}/>:page==='pipeline'?<LocalizedPipeline locale={locale}/>:page==='health'?<LocalizedSystemHealth locale={locale}/>:<LocalizedSettings locale={locale}/>;return <main className={`app-shell ${accessible?'accessible-mode':''}`}><a className="skip-link" href="#main-content">{t(locale,'skip')}</a><aside className="sidebar"><div className="brand"><span className="pulse" aria-hidden="true"/><div><strong>VOICE CIPHER</strong><small>{tx(locale,'brand')}</small></div></div><nav aria-label="Dashboard sections">{nav.map(([id,icon])=><button key={id} aria-current={page===id?'page':undefined} className={page===id?'active':''} onClick={()=>setPage(id)}><span aria-hidden="true">{icon}</span>{navLabel(locale,id)}{id==='cases'&&<em>{cases.length}</em>}</button>)}</nav><div className="sidebar-bottom"><div className="operator-avatar">AP</div><div><b>A. Pandey</b><small>{tx(locale,'operator')}</small></div><span className="online" aria-label="Operator online"/></div></aside><section className="workspace" id="main-content" tabIndex="-1"><div className="top-actions"><span className="api-state">{connected?tx(locale,'liveApi'):tx(locale,'demo')}</span><DashboardControls locale={locale} setLocale={setLocale} accessible={accessible} setAccessible={setAccessible}/><span className="api-state">{tx(locale,'authorized')}</span></div><div className="view-shell" key={page}>{View}</div></section></main>}
